#include <cstddef>
#include <cstdint>
static void put64(std::uint8_t*o,std::size_t i,std::int64_t x){auto v=static_cast<std::uint64_t>(x);for(int b=0;b<8;b++)o[i*8+b]=v>>(b*8);}
extern "C" std::int64_t highest_response_ratio_next(const std::int64_t*v,std::size_t n,std::uint8_t*out,std::size_t cap)noexcept{if(!v||n<3||n>129)return -1;auto count=v[0];if(count<1||count>64||n!=std::size_t(1+2*count))return -1;std::int64_t a[64],b[64],tat[64];bool done[64]={};for(int i=0;i<count;i++){a[i]=v[1+2*i];b[i]=v[2+2*i];if(a[i]<0||a[i]>100000||b[i]<1||b[i]>1000)return -1;}for(int i=1;i<count;i++)for(int j=i;j>0&&a[j]<a[j-1];j--){auto t=a[j];a[j]=a[j-1];a[j-1]=t;t=b[j];b[j]=b[j-1];b[j-1]=t;}if(std::size_t(count)*8>cap||!out)return -2;std::int64_t now=0;for(int step=0;step<count;){int best=-1;std::int64_t num=0;for(int i=0;i<count;i++)if(!done[i]&&a[i]<=now){auto cand=now-a[i]+b[i];if(best<0||cand*b[best]>num*b[i]){best=i;num=cand;}}if(best<0){for(int i=0;i<count;i++)if(!done[i]&&(best<0||a[i]<a[best]))best=i;now=a[best];continue;}tat[best]=now+b[best]-a[best];now+=b[best];done[best]=true;step++;}for(int i=0;i<count;i++)put64(out,i,tat[i]);return count*8;}
